def test_frontend_build_installs_frozen_dependencies_when_canonical_tree_is_invalid(tmp_path, monkeypatch):
    module = load_dispatcher()
    calls = []
    frontend = tmp_path / "frontend"
    frontend.mkdir()
    (frontend / "package.json").write_text('{}', encoding='utf-8')
    (frontend / "yarn.lock").write_text('# lock', encoding='utf-8')

    canonical_root = tmp_path / "canonical-root"
    (canonical_root / "frontend").mkdir(parents=True)
    monkeypatch.setattr(module, "ROOT", canonical_root)

    def fake_run(args, **kwargs):
        calls.append((args, kwargs))
        if args[:2] == ["yarn", "install"]:
            client = frontend / "node_modules" / "react-dom" / "client.js"
            client.parent.mkdir(parents=True, exist_ok=True)
            client.write_text('module.exports={}', encoding='utf-8')
        return SimpleNamespace(returncode=0, stdout='ok')

    monkeypatch.setattr(module, "run", fake_run)
    result = module.run_check(tmp_path, {"type": "frontend_build", "directory": "frontend"})

    assert result["status"] == "PASS"
    assert calls[0][0] == ["yarn", "install", "--frozen-lockfile", "--non-interactive"]
    assert calls[1][0] == ["yarn", "build"]


def test_integrate_retries_auth_without_broken_helper(monkeypatch):
    module = load_dispatcher()
    calls = []

    def fake_git(*args, **kwargs):
        if args[:3] == ("config", "--local", "--get"):
            return SimpleNamespace(returncode=0, stdout="store --file=/safe/credentials\n")
        if args[:2] == ("rev-parse", "origin/Edarsahub_Desarrollo"):
            return SimpleNamespace(returncode=0, stdout="base\n")
        return SimpleNamespace(returncode=0, stdout="")

    def fake_run(args, **kwargs):
        calls.append((args, kwargs))
        if "push" in args and any("credential.helper=store" in item for item in args):
            return SimpleNamespace(returncode=128, stdout="fatal: could not read Username for https://github.com: terminal prompts disabled")
        return SimpleNamespace(returncode=0, stdout="ok")

    monkeypatch.setattr(module, "git", fake_git)
    monkeypatch.setattr(module, "run", fake_run)
    module.integrate("candidate", "base")

    pushes = [args for args, _ in calls if "push" in args]
    assert len(pushes) == 2
    assert any("credential.helper=store --file=/safe/credentials" in item for item in pushes[0])
    assert pushes[1][:3] == ["git", "-c", "credential.helper="]
